function sameStatus(expected, actual) {
  return expected === actual;
}

function missingKeys(expected, actual) {
  return Object.keys(expected).filter((key) => !(key in actual));
}

function sameValue(expectedBody, actualBody, key) {
  return expectedBody[key] === actualBody[key];
}

function verifyContract(interactions, getActual) {
  const failures = [];
  for (const it of interactions) {
    const actual = getActual(it.request);
    const expectedBody = it.response.body ?? {};
    const actualBody = actual.body ?? {};
    const statusOk = actual.status === it.response.status;
    const bodyOk = Object.entries(expectedBody).every(
      ([key, value]) => actualBody[key] === value,
    );
    if (!statusOk || !bodyOk) failures.push(it.description);
  }
  return { passed: failures.length === 0, failures };
}

function failingConsumers(contracts, getActual) {
  const passes = (it) => {
    const actual = getActual(it.request);
    const expectedBody = it.response.body ?? {};
    const actualBody = actual.body ?? {};
    return (
      actual.status === it.response.status &&
      Object.entries(expectedBody).every(([key, value]) => actualBody[key] === value)
    );
  };
  return contracts
    .filter((c) => !c.interactions.every(passes))
    .map((c) => c.consumer);
}

function canIDeploy(version, consumers, results) {
  return consumers.every((consumer) =>
    results.some((r) => r.version === version && r.consumer === consumer && r.passed),
  );
}

function findBrokenFields(expected, actual) {
  return Object.keys(expected).filter((key) => actual[key] !== expected[key]);
}
